INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(111759, 'ruRU', '', 'Если хочешь, я могу отвезти тебя обратно в твой город в небесах. Я вернусь позже за останками Гэлфорда.', 24330),
(111763, 'ruRU', '', '<Призрачная тень задержалась в цитадели — давно умершее воспоминание из прошлого Даларана. Стройная фигура узнаёт твой посох и принимает тебя за кого-то другого. Она ленивым взглядом окидывает тебя сквозь полуприкрытые веки.>$b$bАрхимаг Алоди. Так ты идёшь встретиться с Катра''натиром? Остальной совет игнорирует мои предупреждения.$b$bХорошо же. Я не стану мешать твоему самоубийству. Если хочешь добавить мою силу к своей, тебе нужно лишь попросить.$b$b<Фиора грустно пьёт вино и не смотрит тебе в глаза.>', 24330),
(111764, 'ruRU', '', 'Хорошо же. Используй это с толком, маг.', 24330),
(111765, 'ruRU', '', 'Легион захватил выводок лазурных дракончиков Стеллагозы! Спаси их, чтобы потомство нашей союзницы могло вырасти сильнее!', 24330),
(111766, 'ruRU', '', 'Эти дракончики были такими маленькими, такими беспомощными. Как подло со стороны Легиона охотиться на слабых!', 24330),
(111767, 'ruRU', '', 'Каждый отряд Легиона получает силу от машины душ. Выведи из строя эту мерзкую машину демонов и убей эредаров, что её обслуживают!', 24330),
(111768, 'ruRU', '', 'Превосходно! Им придётся заняться ремонтом, прежде чем их машина душ снова заработает. Ты выиграл для нас ценное время.', 24330),
(111769, 'ruRU', '', 'Мы можем сварить мощное зелье обнаружения демонов, если собрать подходящую кучу внутренностей. Собери их для меня, и вместе мы вернём Фаронаар!', 24330),
(111770, 'ruRU', '', 'Ты уж точно не брезгуешь грязной работой. Молодец.', 24330),
(111771, 'ruRU', '', 'Иногда мне хочется, чтобы исследования Гарухода требовали менее... неприятных реагентов. Увы, эти подойдут. Спасибо.', 24330),
(111779, 'ruRU', '', '<Тёмный силуэт гномки парит перед тобой — далёкое воспоминание из прошлого. Она сосредоточена на мощном заклинании, но принимает тебя за кого-то другого, когда ты подходишь.>\n\nАлоди! Ты вернулся. Дай-ка взглянуть на твой посох. Да, да... Я, конечно, могу тебе помочь. Но тебе стоило бы услышать, что говорит остальной совет за твоей спиной. Твоё счастье, что ты им нужен.', 24330),
(111782, 'ruRU', '', 'Надеюсь, ты знаешь, что делаешь. А если нет... По крайней мере, будет на что посмотреть. Удачи там!', 24330),
(111784, 'ruRU', '', 'Южные врата! Ещё один демон в полях!', 24330),
(111799, 'ruRU', '', 'Наши гиппогрифы хорошо накормлены и готовы доставить тебя куда угодно.', 24330),
(111812, 'ruRU', '', 'Идём дальше.', 24330),
(111813, 'ruRU', '', 'Развей эти воспоминания, чтобы мы могли продолжить.', 24330),
(111814, 'ruRU', '', 'Я теряю контроль...', 24330),
(111816, 'ruRU', '', 'Это именно то, что я делаю.', 24330),
(111818, 'ruRU', '', 'Нам следует планировать нападение на Сурамар!', 24330),
(111837, 'ruRU', '', 'Этого должно хватить, чтобы обмануть болтливых, пропитанных вином гостей, но наблюдательный глаз сможет разгадать обман. Если иллюзия ослабнет, стража быстро набросится на тебя.', 24330),
(111838, 'ruRU', '', 'Приступай. Я готов к маскировке.', 24330),
(111839, 'ruRU', '', 'Это невероятно опасное предложение ты делаешь. Откуда мне знать, что ты действительно говоришь от имени Вантира?', 24330),
(111847, 'ruRU', '', '(CUT)', 24330),
(111849, 'ruRU', '', '(CUT)', 24330),
(111853, 'ruRU', '', '<Покажи Арлуину свою Печать.>', 24330),
(111857, 'ruRU', '', 'Готов ли ты выйти на арену и обрести славу в бесконечном бою?', 24330),
(111859, 'ruRU', '', 'Посмотри на их мявенькие мордашки! Они такие миленькие, что я умираю!', 24330),
(111860, 'ruRU', '', 'Ты весь из себя грозный лай, а укусить-то и не можешь.', 24330),
(111861, 'ruRU', '', 'Хихи!', 24330),
(111862, 'ruRU', '', 'Я сделаю вам, малыши, мявенькие повязочки на ваши мявенькие бо-бо!', 24330),
(111863, 'ruRU', '', 'Солёный?', 24330),
(111864, 'ruRU', '', 'Корги. Ну я же права?', 24330),
(111865, 'ruRU', '', 'Гав.', 24330),
(111866, 'ruRU', '', 'Но он был таким милым!', 24330),
(111867, 'ruRU', '', 'Ты монстр!', 24330),
(111868, 'ruRU', '', 'Ох.', 24330),
(111871, 'ruRU', '', 'Чем скорее я вернусь в город, тем лучше.', 24330),
(111873, 'ruRU', '', 'Не притворяйся. Я знаю, что ты здесь, чтобы шпионить для Великой Магистрикс.', 24330),
(111876, 'ruRU', '', 'Проходи, друг. У меня с тобой никаких дел.', 24330),
(111878, 'ruRU', '', 'Да будет Сурамар вечен, друг.', 24330);
